package com.bank.loan;

import org.springframework.stereotype.Service;
import java.math.BigDecimal;

// Business logic the standard Maven build compiles and tests.
@Service
public class LoanApprovalService {

    private static final BigDecimal MAX_AMOUNT = new BigDecimal("5000000");
    private static final int MIN_CREDIT_SCORE = 700;

    // Rajesh applies for a loan. Approve only if amount and score are in range.
    public boolean isEligible(BigDecimal requestedAmount, int creditScore) {
        if (requestedAmount == null || requestedAmount.signum() <= 0) {
            throw new IllegalArgumentException("amount must be positive");
        }
        boolean amountOk = requestedAmount.compareTo(MAX_AMOUNT) <= 0;
        boolean scoreOk = creditScore >= MIN_CREDIT_SCORE;
        return amountOk && scoreOk;
    }
}
