package com.bank.loan;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;

// Runs automatically in the Maven 'test' phase before 'package'.
class LoanApprovalServiceTest {

    private final LoanApprovalService service = new LoanApprovalService();

    @Test
    void approvesRajeshWithinLimits() {
        assertTrue(service.isEligible(new BigDecimal("2000000"), 760));
    }

    @Test
    void rejectsLowScore() {
        assertFalse(service.isEligible(new BigDecimal("2000000"), 650));
    }
}
